Home range estimation
We delineate individual home ranges by computing minimum convex polygons (MCP) via convex hulls (chull) using projected UTM coordinates. We retain individuals with at least 4 spatially-reference captures and filter out coordinate points \(&gt; 150\text{ m}\) from each individual’s mean centroid to remove GPS artifacts and/or potential misidentifications. The resulting polygon coordinates are saved to data/home_ranges.rds and visualized with site-mean-centered coordinates to compare spatial extents across elevation sites.

home_ranges &lt;- mr_data |&gt;
  filter(if_all(c(lat, lon, utm_x, utm_y), ~ !is.na(.x))) |&gt;
  group_by(site, id, sex) |&gt;
  mutate(
    n_obs = n(),
    mean_utm_x = mean(utm_x),
    mean_utm_y = mean(utm_y),
    dist_to_center = sqrt((utm_x - mean_utm_x)^2 + (utm_y - mean_utm_y)^2)
  ) |&gt;
  filter(
    dist_to_center &lt;= 150,
    n_obs &gt;= 4
  ) |&gt;
  slice(chull(utm_x, utm_y)) |&gt;
  ungroup() |&gt;
  select(site, id, sex, utm_x, utm_y)

saveRDS(home_ranges, file = "data/home_ranges.rds")



Plot lizard home ranges
home_ranges |&gt;
  group_by(site) |&gt;
  mutate(
    x_dim = utm_x - mean(utm_x),
    y_dim = utm_y - mean(utm_y)
  ) |&gt;
  ungroup() |&gt;
  filter(sex == "M") |&gt;
  ggplot(aes(x = x_dim, y = y_dim, color = site)) +
  geom_polygon(aes(group = id), linewidth = 0.5, fill = NA) +
  labs(
    x = "Distance (m, relative to site mean)",
    y = "Distance (m, relative to site mean)"
  ) +
  theme_minimal() +
  scale_color_manual(values = site_colors) +
  facet_wrap(
    ~site, 
    scales = "free",
    space = "free_x",
    labeller = as_labeller(c(
      HE = "High Elevation (HE)",
      LE = "Low Elevation (LE)"
    ))
  ) +
  scale_x_continuous(
    breaks = seq(-400, 400, by = 100)
  ) +
  theme(
    panel.border = element_rect(fill = NA, linewidth = 0.5),
    axis.ticks = element_line(linewidth = 0.25),
    legend.title = element_blank(),
    legend.text = element_text(size = 14),
    strip.text = element_text(size = 14),
    axis.title = element_text(size = 12),
    axis.text = element_text(size = 10),
    panel.grid.minor = element_blank(),
    panel.grid.major = element_line(
      linewidth = 0.25,
      color = "gray80"
    ),
    legend.position = "none"
  )















Note



The “LE” population is divided between two neighbouring outcrops while the “HE” population extends across a continuous area.
